commands.command:
cat /opt/vyatta/share/vyatta-cfg/templates/firewall/ipv4/forward/filter/rule/node.tag/log/node.def
echo ===STATE===
find /opt/vyatta/share/vyatta-cfg/templates/firewall/ipv4/forward/filter/rule/node.tag/state -maxdepth 3
echo ===
cat /opt/vyatta/share/vyatta-cfg/templates/firewall/ipv4/forward/filter/rule/node.tag/state/node.def 2>/dev/null

cat /usr/local/opnsense/service/conf/actions.d/actions_interface.conf 2>/dev/null
echo ===FILTER===
cat /usr/local/opnsense/service/conf/actions.d/actions_filter.conf 2>/dev/null

configctl interface reconfigure opt1 2>&1 | tail -20
echo ===opt2===
configctl interface reconfigure opt2 2>&1 | tail -20

configctl routes configure 2>&1 | tail -20
echo ===netstat===
netstat -rn | grep 10.10
